---@class ClubBossDojo
local ClubBossDojo = Class("ClubBossDojo")

function ClubBossDojo:__init()
    self.atBossPlayerNum = {}
    self.cardDisable = {}
    self.catDisable = {}
    self.dailyBossAtTimesLeft = 0  -- 个人挑战剩余次数
    self.clubBossLog = {}
    self.round = 0
    self.scheduleId = 0
    self.percentageRank = 0
    self.participateTimes = 0
    self.myRank = {}  -- { ranking ,score  }
    self.bossHpInfo = {} --{questId, totalHp, remainingHp}
    self.dailyBossAtTimes = 0  --社团所有人挑占剩余次数Boss
end

---FillVo
---@param row TableML.TableFileRow
function ClubBossDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end
end

function ClubBossDojo:GetPercentRank()
    return checkNumber(self.percentageRank)
end

function ClubBossDojo:GetClubRank()
    return self.myRank.ranking
end

function ClubBossDojo:GetRound()
    return self.round
end

function ClubBossDojo:GetLeaveTimes()
    return self.dailyBossAtTimesLeft
end

function ClubBossDojo:IsHaveTimes()
    return self:GetLeaveTimes() > 0
end

function ClubBossDojo:GetRecord()
    return self.clubBossLog
end

function ClubBossDojo:IsAllBossDie()
    for i, v in pairs(self.bossHpInfo) do
        if checkNumber(v.remainingHp) > 0 then
            return false
        end
    end
    return true
end

function ClubBossDojo:IsAllSmallBossDie()
    for i, v in pairs(self.bossHpInfo) do
        local vo = ClubUtils.GetBossPassVo(v.questId)
        if vo.bossTypes == ClubUtils.BossType.NormalBoss then
            if checkNumber(v.remainingHp) > 0 then
                return false
            end
        end
    end
    return true
end

function ClubBossDojo:GetBossAtNumByQuestId(questId)
    if isNotNull(self.atBossPlayerNum[tostring(questId)]) then
        return checkNumber(self.atBossPlayerNum[tostring(questId)])
    end
    return 0
end

function ClubBossDojo:GetBossInfo()
    return self.bossHpInfo
end

function ClubBossDojo:UpdateClubBossLog(logData)
    table.insert(self.clubBossLog,logData)
end

function ClubBossDojo:GetScheduleId()
    return self.scheduleId
end

function ClubBossDojo:GetCatDisable()
    return self.catDisable
end

function ClubBossDojo:GetCardDisable()
    return self.cardDisable
end

function ClubBossDojo:GetParticipateTimes()
    return checkNumber(self.participateTimes)
end

function ClubBossDojo:IsCanEnter()
    return checkNumber(self.dailyBossAtTimes) > 0
end

function ClubBossDojo:__delete()
    self.cardDisable = nil
    self.catDisable = nil
    self.dailyBossAtTimesLeft = nil
    self.clubBossLog = nil
    self.round = nil
    self.scheduleId = nil
    self.percentageRank = nil
    self.myRank = nil  -- { ranking ,score  }
    self.bossHpInfo = nil --{questId, totalHp, remainingHp}
    self.dailyBossAtTimes = nil
    self.atBossPlayerNum = nil
end

return ClubBossDojo